    "UPDATE agent_attribute_proposal SET state=?,payload=CASE WHEN ? THEN payload ELSE NULL END\n    WHERE proposal_id=? AND request_hash=? AND state='pending' AND expires_at>? AND expires_at>unixepoch()\n    AND EXISTS(SELECT 1 FROM agent_grant g\n JOIN agent_recipient_key rk ON rk.key_id=g.recipient_key_id AND rk.state='active'\n JOIN account_security a ON a.account_id=g.account_id AND a.active=1 AND a.epoch=g.owner_epoch\n JOIN credential c ON c.credential_id=g.credential_id AND c.account_id=g.account_id AND c.active=1\n WHERE g.revoked=0 AND g.expires_at>? AND g.expires_at>unixepoch()\n AND g.recipient_key_id=? AND g.resource=? AND g.encrypted_snapshot IS NOT NULL AND ((g.storage_version=1 AND EXISTS(\n SELECT 1 FROM vault_attribute_head h WHERE h.account_id=g.account_id AND h.attribute_id='name'\n AND h.deleted=0 AND h.revision=g.source_revision)) OR (g.storage_version=2 AND EXISTS(\n SELECT 1 FROM vault_owner_record_head h JOIN vault_owner_key_head k\n ON k.account_id=h.account_id AND k.vault_id=h.vault_id\n WHERE h.account_id=g.account_id AND h.vault_id=g.source_vault_id\n AND h.collection_id=g.source_collection_id AND h.record_id=g.source_record_id\n AND h.kind=g.source_kind AND h.revision=g.source_revision AND h.deleted=0 AND h.format_version=2\n AND h.ciphertext_sha256=g.source_ciphertext_sha256 AND h.key_generation=g.source_key_generation\n AND k.origin=g.source_origin AND k.key_generation=g.source_key_generation\n AND k.revision=g.source_owner_key_revision AND k.format_version=2\n AND k.suite='PRF-HKDF-SHA256-AES256GCM-v2'))) AND g.expires_at>unixepoch() AND g.storage_version=1 AND g.grant_id=agent_attribute_proposal.grant_id\n      AND g.account_id=? AND g.revision=agent_attribute_proposal.grant_revision AND EXISTS(SELECT 1 FROM json_each(g.operations) WHERE value='propose')\n AND EXISTS(SELECT 1 FROM agent_attribute_capability cap WHERE cap.grant_id=g.grant_id\n   AND cap.storage_version=1 AND cap.grant_revision=g.revision AND cap.attribute_id='owner_note'\n   AND cap.base_revision=COALESCE((SELECT revision FROM vault_attribute_head\n WHERE account_id=g.account_id AND attribute_id='owner_note'),0) AND cap.expires_at>? AND cap.expires_at>unixepoch())\n      AND COALESCE((SELECT revision FROM vault_attribute_head\n WHERE account_id=g.account_id AND attribute_id='owner_note'),0)=agent_attribute_proposal.base_revision AND EXISTS(SELECT 1 FROM sso_context sx JOIN sso_session ss ON ss.sso_id=sx.sso_id\n JOIN account_security a ON a.account_id=ss.account_id AND a.active=1 AND a.epoch=ss.epoch\n JOIN credential c ON c.credential_id=ss.credential_id AND c.account_id=ss.account_id AND c.active=1\n WHERE sx.secret_hash=? AND ss.account_id=? AND ss.revoked=0 AND ss.expires_at>? AND ss.expires_at>unixepoch() AND ss.expires_at>unixepoch()))",
