  e08d2183772eb96ceba99934a70d111f55f9ab6ae68710f17a733bdafcbb25c0:
    "SELECT p.* FROM agent_attribute_proposal p WHERE p.proposal_id=? AND p.request_hash=? AND p.storage_version=2\n    AND p.state='approved' AND p.payload IS NOT NULL AND p.expires_at>unixepoch()\n    AND EXISTS(SELECT 1 FROM agent_grant g\n JOIN agent_recipient_key rk ON rk.key_id=g.recipient_key_id AND rk.state='active'\n JOIN account_security a ON a.account_id=g.account_id AND a.active=1 AND a.epoch=g.owner_epoch\n JOIN credential c ON c.credential_id=g.credential_id AND c.account_id=g.account_id AND c.active=1\n WHERE g.revoked=0 AND g.expires_at>? AND g.expires_at>unixepoch()\n AND g.recipient_key_id=? AND g.resource=? AND g.encrypted_snapshot IS NOT NULL AND ((g.storage_version=1 AND EXISTS(\n SELECT 1 FROM vault_attribute_head h WHERE h.account_id=g.account_id AND h.attribute_id='name'\n AND h.deleted=0 AND h.revision=g.source_revision)) OR (g.storage_version=2 AND EXISTS(\n SELECT 1 FROM vault_owner_record_head h JOIN vault_owner_key_head k\n ON k.account_id=h.account_id AND k.vault_id=h.vault_id\n WHERE h.account_id=g.account_id AND h.vault_id=g.source_vault_id\n AND h.collection_id=g.source_collection_id AND h.record_id=g.source_record_id\n AND h.kind=g.source_kind AND h.revision=g.source_revision AND h.deleted=0 AND h.format_version=2\n AND h.ciphertext_sha256=g.source_ciphertext_sha256 AND h.key_generation=g.source_key_generation\n AND k.origin=g.source_origin AND k.key_generation=g.source_key_generation\n AND k.revision=g.source_owner_key_revision AND k.format_version=2\n AND k.suite='PRF-HKDF-SHA256-AES256GCM-v2'))) AND g.account_id=? AND (g.storage_version=2 AND EXISTS(SELECT 1 FROM json_each(g.operations) WHERE value='propose')) AND (g.grant_id=p.grant_id AND g.revision=p.grant_revision)\n    AND EXISTS(SELECT 1 FROM agent_attribute_capability cap WHERE cap.grant_id=g.grant_id\n      AND ((g.storage_version=2 AND EXISTS(SELECT 1 FROM json_each(g.operations) WHERE value='propose')) AND (cap.grant_revision=g.revision AND cap.expires_at>unixepoch()\n    AND cap.expires_at<=g.expires_at) AND (cap.storage_version=2 AND EXISTS(SELECT 1 FROM vault_owner_key_head k\n    WHERE k.account_id=g.account_id AND k.vault_id=cap.target_vault_id AND k.origin=cap.target_origin\n      AND k.format_version=2 AND k.suite='PRF-HKDF-SHA256-AES256GCM-v2'\n      AND k.key_generation=cap.target_key_generation AND k.revision=cap.target_owner_key_revision)\n    AND ((cap.base_revision=0 AND cap.target_deleted=0 AND cap.target_ciphertext_sha256 IS NULL\n      AND NOT EXISTS(SELECT 1 FROM vault_owner_record_head h WHERE h.account_id=g.account_id\n        AND h.vault_id=cap.target_vault_id AND h.collection_id=cap.target_collection_id AND h.record_id=cap.target_record_id))\n    OR (cap.base_revision>0 AND EXISTS(SELECT 1 FROM vault_owner_record_head h WHERE h.account_id=g.account_id\n      AND h.vault_id=cap.target_vault_id AND h.collection_id=cap.target_collection_id AND h.record_id=cap.target_record_id\n      AND h.kind=cap.target_kind AND h.format_version=2 AND h.revision=cap.base_revision\n      AND h.key_generation=cap.target_key_generation AND h.deleted=cap.target_deleted\n      AND h.ciphertext_sha256 IS cap.target_ciphertext_sha256))))) AND cap.expires_at>=p.expires_at AND (cap.base_revision=p.base_revision AND cap.storage_version IS p.storage_version AND cap.target_origin IS p.target_origin AND cap.target_vault_id IS p.target_vault_id AND cap.target_collection_id IS p.target_collection_id AND cap.target_record_id IS p.target_record_id AND cap.target_kind IS p.target_kind AND cap.target_ciphertext_sha256 IS p.target_ciphertext_sha256 AND cap.target_deleted IS p.target_deleted AND cap.target_key_generation IS p.target_key_generation AND cap.target_owner_key_revision IS p.target_owner_key_revision)) AND EXISTS(SELECT 1 FROM sso_context sx JOIN sso_session ss ON ss.sso_id=sx.sso_id\n JOIN account_security a ON a.account_id=ss.account_id AND a.active=1 AND a.epoch=ss.epoch\n JOIN credential c ON c.credential_id=ss.credential_id AND c.account_id=ss.account_id AND c.active=1\n WHERE sx.secret_hash=? AND ss.account_id=? AND ss.revoked=0 AND ss.expires_at>? AND ss.expires_at>unixepoch() AND EXISTS(SELECT 1 FROM vault_owner_key_wrap w\n    WHERE w.account_id=ss.account_id AND w.key_generation=p.target_key_generation AND w.credential_id=ss.credential_id)))",
